set -euo pipefail

usage() {
    cat <<'USAGE'
Usage: scripts/run-sparse-join-aggregate-benchmarks.sh [options]

Run independently verified, complete join-aggregate queries in fresh JVM forks.
The sparse kernel's per-query remapping/setup is included. Persistent adjacency
construction and fixture loading are separately recorded. Every measured result
is checked against the exact weighted oracle after the timer stops.

  --no-build                 Use the existing LMDB target/jmh-benchmarks.jar
  --output DIR               Results directory (default target/sparse-join-TIMESTAMP)
  --forks N                  Independent JVM processes (default 3)
  --fanouts LIST             Distinct neighbors per join key (default 1,8,32)
  --blocks LIST              Endpoint partitions (default 1,8)
  --multiplicities LIST      Maximum context weight (default 1,4)
  --thresholds LIST          none,median,empty or integer thresholds
  --counts LIST              bound for COUNT(?z), star for COUNT(*) (default bound)
  --routes LIST              auto,packedFtreeAggregate,sparseJoinAggregate (default)
  --endpoints N              Each endpoint domain size (default 256)
  --join-keys N              Number of shared values (default 512)
  --warmups N                Untimed verified queries per case (default 3)
  --iterations N             Timed verified queries per case (default 7)
  --heap SIZE                Maximum Java heap (default 3G)
  --help                     Show this message

MVN selects the Maven executable; JAVA_HOME or JAVA selects Java. Build first
tries offline, then retries online if dependencies are missing. Benchmarks run
serially; do not run builds or tests concurrently with measurements. See
scripts/sparse-join-aggregate-benchmarks.md for JMH and interpretation guidance.
USAGE
}

script_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
repo_root="$(cd -- "${script_dir}/.." && pwd)"
cd "${repo_root}"
build=true
output="${repo_root}/target/sparse-join-$(date -u +%Y%m%dT%H%M%SZ)"
forks=3
heap=3G
runner_args=()
while [[ $# -gt 0 ]]; do
    case "$1" in
        --no-build) build=false; shift ;;
        --output) output="$2"; shift 2 ;;
        --forks) forks="$2"; shift 2 ;;
        --heap) heap="$2"; shift 2 ;;
        --fanouts|--blocks|--multiplicities|--thresholds|--counts|--routes|--endpoints|--join-keys|--warmups|--iterations)
            runner_args+=("$1" "$2"); shift 2 ;;
        --help|-h) usage; exit 0 ;;
        *) printf 'Unknown argument: %s\n' "$1" >&2; usage >&2; exit 2 ;;
    esac
done
if [[ ! "${forks}" =~ ^[1-9][0-9]*$ ]]; then
    printf '%s\n' '--forks must be a positive integer' >&2
    exit 2
fi
mkdir -p -- "${output}"
output="$(cd -- "${output}" && pwd)"
for previous_run in "${output}"/fork-*.csv "${output}/environment.txt" "${output}/commands.sh"; do
    if [[ -e "${previous_run}" ]]; then
        printf 'Refusing to mix results with an earlier run in %s; select a new --output directory.\n' "${output}" >&2
        exit 2
    fi
done
java_command="${JAVA:-${JAVA_HOME:+${JAVA_HOME}/bin/}java}"
mvn_command="${MVN:-mvn}"
benchmark_class=org.eclipse.rdf4j.sail.lmdb.benchmark.SparseJoinAggregateBenchmark
jar_path="${repo_root}/core/sail/lmdb/target/jmh-benchmarks.jar"

if ${build}; then
    # -am is used only for packaging with tests skipped by the repository quick profile.
    build_args=(-B -ntp -Dmaven.repo.local=.m2_repo -pl core/sail/lmdb -am -Pbenchmarks,quick package)
    if ! "${mvn_command}" -o "${build_args[@]}" >"${output}/build-offline.log" 2>&1; then
        printf '%s\n' 'Offline packaging failed; retrying with dependency downloads.'
        "${mvn_command}" "${build_args[@]}" >"${output}/build-online.log" 2>&1
    fi
fi
if [[ ! -f "${jar_path}" ]]; then
    printf 'Missing benchmark jar: %s\n' "${jar_path}" >&2
    exit 1
fi

{
    date -u +%FT%TZ
    git rev-parse HEAD
    git status --short
    uname -a
    "${java_command}" -version 2>&1
    if command -v lscpu >/dev/null 2>&1; then lscpu; fi
    for resource_file in /sys/fs/cgroup/cpu.max /sys/fs/cgroup/memory.max; do
        if [[ -r "${resource_file}" ]]; then
            printf '%s: ' "${resource_file}"
            cat "${resource_file}"
        fi
    done
    printf 'heap=%s\nforks=%s\n' "${heap}" "${forks}"
    if command -v sha256sum >/dev/null 2>&1; then sha256sum "${jar_path}"; fi
    printf '%s\n' 'Native evaluation and serial execution are enabled for all routes.'
    printf '%s\n' 'auto uses sparse=false; sparseJoinAggregate and autoSparse use sparse=true.'
    printf '%s\n' 'first means first query for that route/threshold on an already loaded, adjacency-built store.'
    printf '%s\n' 'No filesystem-cache eviction is performed; first is not cold-disk latency.'
    printf '%s\n' 'Query time includes parse/prepare, optimize, per-query setup/remap, aggregate and result collection.'
    printf '%s\n' 'Exact result validation and persistent fixture/index setup are outside query time.'
} >"${output}/environment.txt"
git diff --binary HEAD >"${output}/working-tree.patch"
# Include new implementation/tests as well when reproducing an uncommitted feature.
while IFS= read -r -d '' source_file; do
    diff_status=0
    git diff --no-index --binary -- /dev/null "${source_file}" >>"${output}/working-tree.patch" || diff_status=$?
    if ((diff_status > 1)); then exit "${diff_status}"; fi
done < <(git ls-files --others --exclude-standard -z -- \
    core/sail/lmdb/src/main/java/org/eclipse/rdf4j/sail/lmdb/evaluation \
    core/sail/lmdb/src/test/java/org/eclipse/rdf4j/sail/lmdb/evaluation \
    core/sail/lmdb/src/test/java/org/eclipse/rdf4j/sail/lmdb/benchmark/SparseJoinAggregateBenchmark.java \
    scripts/run-sparse-join-aggregate-benchmarks.sh \
    scripts/summarize-sparse-join-aggregate.py \
    scripts/sparse-join-aggregate-benchmarks.md)
for ((fork = 0; fork < forks; fork++)); do
    command=("${java_command}" -Xms1G "-Xmx${heap}" -cp "${jar_path}" "${benchmark_class}"
        --fork "${fork}" --output "${output}/fork-${fork}.csv" "${runner_args[@]}")
    printf '%q ' "${command[@]}" >>"${output}/commands.sh"
    printf '\n' >>"${output}/commands.sh"
    "${command[@]}" 2>&1 | tee "${output}/fork-${fork}.log"
done
python3 "${script_dir}/summarize-sparse-join-aggregate.py" "${output}"
printf 'Verified raw results: %s\n' "${output}"
